function drawLocalGacha(currency,count,slot){const cost=currency==='gold'?(count===1?500:4500):(count===1?100:900);if(data[currency]<cost)throw Error(currency==='gold'?'골드가 부족합니다.':'캐시가 부족합니다.');const before=JSON.parse(JSON.stringify(data));data[currency]-=cost;const results=[],newItems=[];let rarePlus=false,duplicateCount=0,goldRefund=0;for(let index=0;index<count;index++){let forcedRarity=null;if(data.summonPity.legendary>=99)forcedRarity='legendary';else if(data.summonPity.epic>=29)forcedRarity='epic';else if(count===10&&index===count-1&&!rarePlus)forcedRarity='rare';const item=generateLocalGachaGear(levelFor(data.xp).level,slot,forcedRarity),isEpicPlus=['epic','unique','legendary','mythic','immortal'].includes(item.rarity);data.summonPity.legendary=['legendary','mythic','immortal'].includes(item.rarity)?0:Math.min(99,data.summonPity.legendary+1);data.summonPity.epic=isEpicPlus?0:Math.min(29,data.summonPity.epic+1);rarePlus||=['rare','epic','unique','legendary','mythic','immortal'].includes(item.rarity);const duplicate=data.items.some(existing=>existing.slot===item.slot&&existing.name===item.name)||newItems.some(existing=>existing.slot===item.slot&&existing.name===item.name);if(duplicate){item.duplicate=true;item.goldRefund=DUPLICATE_GOLD[item.rarity];duplicateCount++;goldRefund+=item.goldRefund}else newItems.push(item);results.push(item)}if(data.items.length+newItems.length>60){data=before;throw Error('장비 가방 공간이 부족합니다. 중복 장비는 골드로 보상됩니다.')}data.items.push(...newItems);data.gold=Math.min(9999999,data.gold+goldRefund);const history={at:Date.now(),currency,count,cost,slot,duplicateCount,goldRefund,items:results.map(item=>({name:item.name,slot:item.slot,rarity:item.rarity,duplicate:item.duplicate===true,goldRefund:item.goldRefund||0}))};data.summonHistory=[history,...data.summonHistory].slice(0,10);return{ok:true,currency,count,cost,slot,items:results,duplicateCount,goldRefund,state:data}}
async function drawGacha(currency,count,slot='weapon'){if(gachaBusy)return;gachaBusy=true;document.querySelectorAll('[data-gacha]').forEach(button=>button.disabled=true);clearTimeout(saveTimer);try{while(saving)await new Promise(resolve=>setTimeout(resolve,50));if(dirty)await flushSave(true);if(dirty)throw Error('현재 진행도를 저장한 뒤 다시 뽑아 주세요.');const outcome=devMode?drawLocalGacha(currency,count,slot):await request('/api/rpg/gacha',{currency,count,slot});data=normalizeSave(outcome.state);if(devMode)localStorage.setItem(devSaveKey,JSON.stringify({character:activeCharacter,state:data}));dirty=false;lastSave=Date.now();$('gacha-results').innerHTML='<div class="gacha-result-heading">'+SLOT_LABEL[slot]+' '+count+'회 소환 결과 <small>'+(currency==='gold'?'골드':'캐시')+' '+outcome.cost.toLocaleString()+' 사용 · 중복 보상 골드 '+Number(outcome.goldRefund||0).toLocaleString()+'</small></div><div class="gacha-result-grid">'+outcome.items.map(item=>'<div class="gacha-result rarity-border-'+item.rarity+'"><div class="loot-art rarity-border-'+item.rarity+'">'+(getEquipmentIcon(item)?'<img src="'+escapeHtml(getEquipmentIcon(item))+'" alt="" loading="lazy">':'')+'<small>'+RARITY_LABEL[item.rarity]+'</small></div><b class="rarity-'+item.rarity+'">'+escapeHtml(item.name)+'</b><small>'+SLOT_LABEL[item.slot]+' · '+RARITY_LABEL[item.rarity]+(item.duplicate?' · 중복 → 골드 +'+item.goldRefund:'')+'</small></div>').join('')+'</div>';showState();renderGear();toast(SLOT_LABEL[slot]+' '+count+'회 뽑기 완료 · 중복 '+(outcome.duplicateCount||0)+'개 골드 보상')}catch(error){toast(error.message)}finally{gachaBusy=false;if(dirty)queueSave();refreshGachaButtons()}}
function refreshGachaButtons(){document.querySelectorAll('[data-gacha]').forEach(button=>{const[currency,count]=button.dataset.gacha.split(':'),price=Number(currency==='gold'?(count==='1'?500:4500):(count==='1'?100:900));button.disabled=gachaBusy||data[currency]<price})}
$('shop').addEventListener('click',e=>{const button=e.target.closest('[data-gacha]');if(!button)return;const[currency,count,slot='weapon']=button.dataset.gacha.split(':');drawGacha(currency,Number(count),slot)});document.querySelector('.auto-settings').addEventListener('change',()=>{data.autoSettings=normalizeAutoSettings({range:$('auto-range').value,target:$('auto-target').value,potionAt:$('auto-potion').value,autoQuest:$('auto-quest').checked,arrowType:$('archer-arrow').value,autoSkills:$('archer-auto-skills').checked});queueSave();toast('자동전투 설정을 저장했습니다.')});
function showState(){const lv=levelFor(data.xp),cls=CLASS_INFO[data.classId]||CLASS_INFO.warrior,stats=combatStats();$('hero-name').textContent=activeCharacter?.name||username;$('hero-level').textContent=`Lv. ${lv.level} · ${cls.label}`;$('health-bar').style.width=(data.hp/stats.maxHp*100)+'%';$('health-text').textContent='HP '+Math.ceil(data.hp)+' / '+stats.maxHp;$('xp-bar').style.width=(lv.progress/lv.needed*100)+'%';$('xp-text').textContent='XP '+Math.floor(lv.progress)+' / '+lv.needed;$('gold').textContent='◈ '+Math.floor(data.gold);$('cash').textContent='✧ '+Math.floor(data.cash);$('combat-power-header').textContent=stats.power.toLocaleString();$('combat-power').textContent=stats.power.toLocaleString();$('attack-stat').textContent=stats.atk.toLocaleString();$('defense-stat').textContent=stats.def.toLocaleString();$('inventory-summary').textContent=`${cls.label} Lv. ${lv.level} · ◈ ${Math.floor(data.gold)} · ✧ ${Math.floor(data.cash)}`;$('quest-title').textContent=data.questStage===0?'숲길 정찰':data.questStage===1?'고블린 야영지':'변경의 수호자';$('quest-copy').textContent=data.questStage===0?'숲길의 슬라임을 처치하고 미라에게 말을 거세요.':data.questStage===1?'고블린 5마리를 처치한 뒤 미라에게 보고하세요.':'숲을 탐험하며 새로운 의뢰를 기다리세요.';const need=data.questStage===0?3:data.questStage===1?5:0,progress=data.questStage===0?Math.min(data.questKills,3):data.questStage===1?Math.min(data.questKills,5):0;$('quest-bar').style.width=(need?progress/need*100:100)+'%';$('quest-count').textContent=need?`${progress} / ${need}`:'완료'}
function queueSave(){if((!token&&!devMode)||!playing||gachaBusy)return;dirty=true;$('save-status').textContent='저장 대기 중…';clearTimeout(saveTimer);saveTimer=setTimeout(flushSave,1100)}
