function showDamageNumber(target,amount,now=performance.now(),critical=false){if(floatingDamage.length>=18)floatingDamage.splice(0,floatingDamage.length-17);const same=floatingDamage.filter(item=>Math.abs(item.x-target.x)<22&&now-item.start<300).length;floatingDamage.push({x:target.x+(same%3-1)*18,y:target.y-34-Math.floor(same/3)*12,text:(critical?'치명타 ':'')+'-'+Math.round(amount),critical,start:now,duration:critical?1100:900})}
